// ✅ NEW: The server load runs during SSR (and server-side navigation),
// fetching data before the page renders. The result is serialized into
// the HTML and hydrated on the client — no flash, SEO-friendly.
export const load = async ({ fetch }) => {
  const res = await fetch('/api/users'); // ✅ NEW: server-side fetch
  const users = await res.json();
  return { users }; // ✅ NEW: shipped to the page via devalue
};

